cssCode:
.slider-wrap {
  width: 280px; height: 60px; background: rgba(255,255,255,0.1);
  border-radius: 30px; position: relative; overflow: hidden;
  box-shadow: inset 0 0 10px rgba(0,0,0,0.5); border: 1px solid rgba(255,255,255,0.2);
}
.slider-text {
  position: absolute; width: 100%; height: 100%;
  display: flex; align-items: center; justify-content: center;
  color: #aaa; font-family: sans-serif; font-weight: bold; pointer-events: none;
}
.slider-bg {
  position: absolute; top: 0; left: 0; height: 100%; width: 0;
  background: linear-gradient(90deg, #00ffcc, #00b386);
  border-radius: 30px;
}
.slider-thumb {
  position: absolute; top: 5px; left: 5px; width: 50px; height: 50px;
  background: #fff; border-radius: 50%; display: flex; align-items: center; justify-content: center;
  color: #000; font-size: 20px; font-weight: bold; cursor: grab; touch-action: none;
  box-shadow: 0 0 10px rgba(0,0,0,0.3); z-index: 10; transition: left 0.3s;
}
.slider-thumb:active { cursor: grabbing; }
.slider-wrap.unlocked .slider-thumb { transition: none; }

jsCode:
const c = document.getElementById('container');
c.style.cssText = 'width:100%;height:100%;display:flex;align-items:center;justify-content:center;background:transparent;';

const wrap = document.createElement('div');
wrap.className = 'slider-wrap';

const bg = document.createElement('div');
bg.className = 'slider-bg';

const text = document.createElement('div');
text.className = 'slider-text';
text.innerText = 'SLIDE TO PAY >>';

const thumb = document.createElement('div');
thumb.className = 'slider-thumb';
thumb.innerText = '💲';

wrap.appendChild(bg); wrap.appendChild(text); wrap.appendChild(thumb);
c.appendChild(wrap);

let isDragging = false, startX = 0, currentLeft = 5;
const maxLeft = 280 - 55;

thumb.addEventListener('pointerdown', (e) => {
  isDragging = true; startX = e.clientX; wrap.classList.add('unlocked');
});

document.addEventListener('pointermove', (e) => {
  if (!isDragging) return;
  let diff = e.clientX - startX;
  let newLeft = 5 + diff;
  if (newLeft < 5) newLeft = 5;
  if (newLeft > maxLeft) newLeft = maxLeft;
  currentLeft = newLeft;
  thumb.style.left = `${newLeft}px`;
  bg.style.width = `${newLeft + 25}px`;
});

document.addEventListener('pointerup', () => {
  if (!isDragging) return;
  isDragging = false;
  wrap.classList.remove('unlocked');
  if (currentLeft > maxLeft - 10) {
    thumb.style.left = `${maxLeft}px`;
    bg.style.width = '100%';
    text.innerText = 'PAYMENT SUCCESS ✓';
    text.style.color = '#fff';
    text.style.zIndex = '20';
  } else {
    thumb.style.left = '5px';
    bg.style.width = '0px';
  }
});
